def orient(m, op):
    pts=list(m)
    # normalized shape, transform around coordinates
    vals=[]
    for r,c in pts:
        if op>=4: c=-c
        for _ in range(op%4): r,c=c,-r
        vals.append((r,c))
    mr=min(r for r,c in vals); mc=min(c for r,c in vals)
    return {(r-mr,c-mc) for r,c in vals}
def matches(g,m, vals={0}):
    H,W=len(g),len(g[0]); res={}
    for op in range(8):
        s=orient(m,op); h=max(r for r,c in s)+1; w=max(c for r,c in s)+1
        hits=[]
        for r in range(H-h+1):
            for c in range(W-w+1):
                if all(g[r+dr][c+dc] in vals for dr,dc in s): hits.append((r,c,s))
        res[op]=hits
    return res
